# Caesar shift review — work through each step below
def encrypt(text, shift):
    out = ""
    for ch in text:
        if ch.isalpha():
            b = ord("A") if ch.isupper() else ord("a")
            out += chr((ord(ch)-b+shift)%26+b)
        else:
            out += ch
    return out
